CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','driver','parent') NOT NULL DEFAULT 'parent',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY users_email_unique(email));
CREATE TABLE IF NOT EXISTS buses (id INT AUTO_INCREMENT PRIMARY KEY,busNumber VARCHAR(50) NOT NULL,driver_id INT NULL,route VARCHAR(255) NOT NULL,status ENUM('Parked','On Trip','Maintenance') NOT NULL DEFAULT 'Parked',lat DECIMAL(10,8) NULL,lng DECIMAL(11,8) NULL,current_stop VARCHAR(255) NULL,last_location_at DATETIME NULL,UNIQUE KEY buses_number_unique(busNumber),UNIQUE KEY buses_driver_unique(driver_id),CONSTRAINT buses_driver_fk FOREIGN KEY(driver_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS bus_stops (id INT AUTO_INCREMENT PRIMARY KEY,bus_id INT NOT NULL,stop_name VARCHAR(255) NOT NULL,stop_lat DECIMAL(10,8) NOT NULL,stop_lng DECIMAL(11,8) NOT NULL,stop_order INT NOT NULL,UNIQUE KEY stop_order_unique(bus_id,stop_order),CONSTRAINT stops_bus_fk FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,parent_id INT NOT NULL,bus_id INT NOT NULL,stop_id INT NULL,CONSTRAINT student_parent_fk FOREIGN KEY(parent_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT student_bus_fk FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE RESTRICT,CONSTRAINT student_stop_fk FOREIGN KEY(stop_id) REFERENCES bus_stops(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,bus_id INT NOT NULL,parent_id INT NOT NULL,trip_date DATE NOT NULL,is_present BOOLEAN NOT NULL,marked_at DATETIME NOT NULL,UNIQUE KEY attendance_once_per_day(student_id,trip_date),CONSTRAINT attendance_student_fk FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,CONSTRAINT attendance_bus_fk FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE RESTRICT,CONSTRAINT attendance_parent_fk FOREIGN KEY(parent_id) REFERENCES users(id) ON DELETE RESTRICT);
